import sys, threading, json, urllib.error
from http.server import HTTPServer, BaseHTTPRequestHandler
sys.path.insert(0, '.')
import importlib, weather; importlib.reload(weather)
state = {'n':0, 'fail':0, 'code':503}
class H(BaseHTTPRequestHandler):
    def log_message(self,*a): pass
    def do_GET(self):
        state['n'] += 1
        if state['n'] <= state['fail']:
            self.send_response(state['code']); self.end_headers(); return
        b = json.dumps({'ok':True}).encode(); self.send_response(200); self.end_headers(); self.wfile.write(b)
srv = HTTPServer(('127.0.0.1',0),H); threading.Thread(target=srv.serve_forever,daemon=True).start()
weather.WeatherClient.BACKOFF_BASE = 0.01
c = weather.WeatherClient(f'http://127.0.0.1:{srv.server_port}')
def run(fail, code=503):
    state.update(n=0, fail=fail, code=code)
    try: r = c.get('x')
    except urllib.error.HTTPError as e: r = f'HTTPError {e.code}'
    return r, state['n']
print(run(0), run(2), run(3), run(5, 500))
srv.shutdown()

